const cfg = $('Config (edit me)').first().json;
const TZ = cfg.timezone || 'Asia/Kolkata';
const todayMD = new Intl.DateTimeFormat('en-CA', {
  timeZone: TZ,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
})
  .format(new Date())
  .slice(5);

function toMD(v) {
  if (v == null || v === '') return null;
  if (typeof v === 'number') {
    const d = new Date(Date.UTC(1899, 11, 30) + v * 864e5);
    return `${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (m) {
    const day = +m[1];
    const month = +m[2];
    return `${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  }
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return null;
  return `${String(d.getUTCMonth() + 1).padStart(2, '0')}-${String(d.getUTCDate()).padStart(2, '0')}`;
}

const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const name = row.Name || row.name;
  const bday = row.DOB || row.Dob || row.dob || row.Birthday || row.birthday;
  const md = toMD(bday);
  if (!name || !md || md !== todayMD) continue;
  out.push({ json: { text: `🎉🎂 Happy Birthday ${String(name).trim()}` } });
}
return out;

for (const item of $input.all()) {
  const body = item.json;
  if (body && body.ok === false) {
    const e = body.error;
    const hint =
      e === 'not_authed' || e === 'invalid_auth' || e === 'token_revoked' || e === 'token_expired'
        ? ' — check SLACK_BOT_TOKEN (Bot User OAuth Token, xoxb-…).'
        : e === 'channel_not_found'
          ? ' — SLACK_CHANNEL must be a channel ID (C…) and invite the bot (/invite @YourBot).'
          : e === 'not_in_channel'
            ? ' — invite the bot to the channel first.'
            : e === 'no_permission' || e === 'missing_scope'
              ? ' — bot needs chat:write (and invite it to the channel).'
              : '';
    throw new Error('Slack API error: ' + e + hint);
  }
}
return $input.all();
